<?php

namespace App\Modules\Crm\Controllers;

use App\Http\Controllers\Controller;
use App\Models\User;
use App\Modules\Crm\Models\Activity;
use App\Modules\Crm\Models\Opportunity;
use App\Modules\Crm\Models\SalesTeam;
use Carbon\Carbon;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;
use Illuminate\View\View;
use Symfony\Component\HttpFoundation\StreamedResponse;

final class CalendarController extends Controller
{
    public function index(Request $request):View
    {
        $filters=$this->filters($request);return view('Crm::calendar.index',['filters'=>$filters,'teams'=>$this->teams($request)->get(['id','name']),'selectedUser'=>$filters['user_id']?User::find($filters['user_id']):null]);
    }
    public function data(Request $request):JsonResponse
    {
        $filters=$this->filters($request);[$from,$to]=$this->range($filters['view'],$filters['date']);$memberIds=$this->memberIds($request,$filters['team_id'],$filters['user_id']);$branchId=$this->branchId($request);$activities=Activity::query()->with(['opportunity:id,title,branch_id,party_id','opportunity.party:id,code,name','assignee:id,name'])->whereBetween('due_at',[$from,$to])->whereHas('opportunity',fn(Builder $query)=>$query->where('branch_id',$branchId))->when($memberIds!==null,fn(Builder $query)=>$query->whereIn('assigned_to',$memberIds))->when($filters['type'],fn(Builder $query)=>$query->where('type',$filters['type']))->when($filters['status']==='OPEN',fn(Builder $query)=>$query->whereNull('completed_at'))->when($filters['status']==='COMPLETED',fn(Builder $query)=>$query->whereNotNull('completed_at'))->orderBy('due_at')->orderBy('id')->limit(501)->get();$activityKeys=$activities->map(fn(Activity $activity)=>$activity->opportunity_id.'|'.($activity->due_at?->format('Y-m-d H:i:s')??''))->all();$nextActions=$filters['status']==='COMPLETED'||$filters['type']?collect():Opportunity::query()->with(['party:id,code,name','owner:id,name'])->where('branch_id',$branchId)->whereBetween('next_action_at',[$from,$to])->when($memberIds!==null,fn(Builder $query)=>$query->whereIn('owner_id',$memberIds))->whereIn('stage',['NEW','CONTACTED','QUALIFIED','PROPOSAL','NEGOTIATION'])->orderBy('next_action_at')->limit(501)->get()->reject(fn(Opportunity $opportunity)=>in_array($opportunity->id.'|'.($opportunity->next_action_at?->format('Y-m-d H:i:s')??''),$activityKeys,true));$truncated=$activities->count()>500||$nextActions->count()>500;$events=$activities->take(500)->map(fn(Activity $activity)=>['kind'=>'ACTIVITY','id'=>$activity->id,'date'=>$activity->due_at->toDateString(),'time'=>$activity->due_at->format('H:i'),'title'=>$activity->subject,'type'=>$activity->type,'completed'=>(bool)$activity->completed_at,'owner'=>$activity->assignee?->name,'customer'=>$activity->opportunity?->party?->name,'opportunity'=>$activity->opportunity?->title,'opportunity_id'=>$activity->opportunity_id,'details'=>$activity->details,'due_at'=>$activity->due_at->format('Y-m-d\\TH:i'),'assigned_to'=>$activity->assigned_to,'url'=>route('crm.opportunities.show',$activity->opportunity_id),'google_url'=>$this->googleCalendarUrl($activity),'update_url'=>!$activity->completed_at&&$request->user()->hasPermission('crm.activities.update')?route('crm.opportunities.activities.update',[$activity->opportunity_id,$activity->id]):null,'schedule_url'=>!$activity->completed_at&&$request->user()->hasPermission('crm.activities.update')?route('crm.opportunities.activities.schedule',[$activity->opportunity_id,$activity->id]):null,'complete_url'=>!$activity->completed_at&&$request->user()->hasPermission('crm.activities.complete')?route('crm.opportunities.activities.complete',[$activity->opportunity_id,$activity->id]):null])->concat($nextActions->take(500)->map(fn(Opportunity $opportunity)=>['kind'=>'NEXT_ACTION','id'=>$opportunity->id,'date'=>$opportunity->next_action_at->toDateString(),'time'=>$opportunity->next_action_at->format('H:i'),'title'=>'Next action: '.$opportunity->title,'type'=>'NEXT_ACTION','completed'=>false,'owner'=>$opportunity->owner?->name,'customer'=>$opportunity->party?->name,'opportunity'=>$opportunity->title,'opportunity_id'=>$opportunity->id,'details'=>null,'due_at'=>$opportunity->next_action_at->format('Y-m-d\\TH:i'),'assigned_to'=>$opportunity->owner_id,'url'=>route('crm.opportunities.show',$opportunity),'google_url'=>null,'update_url'=>null,'schedule_url'=>null,'complete_url'=>null]))->sortBy(fn($event)=>$event['date'].' '.$event['time'])->values();return response()->json(['events'=>$events,'from'=>$from->toDateString(),'to'=>$to->toDateString(),'label'=>$this->label($filters['view'],$from,$to),'truncated'=>$truncated]);
    }
    public function export(Request $request):StreamedResponse
    {
        $filters=$this->filters($request);[$from,$to]=$this->range($filters['view'],$filters['date']);
        throw_if($from->diffInDays($to)>90,ValidationException::withMessages(['date'=>'ส่งออกปฏิทินได้ไม่เกิน 90 วันต่อครั้ง']));
        $memberIds=$this->memberIds($request,$filters['team_id'],$filters['user_id']);
        $activities=Activity::query()->whereBetween('due_at',[$from,$to])->whereHas('opportunity',fn(Builder $query)=>$query->where('branch_id',$this->branchId($request)))->when($memberIds!==null,fn(Builder $query)=>$query->whereIn('assigned_to',$memberIds))->when($filters['type'],fn(Builder $query)=>$query->where('type',$filters['type']))->when($filters['status']==='OPEN',fn(Builder $query)=>$query->whereNull('completed_at'))->when($filters['status']==='COMPLETED',fn(Builder $query)=>$query->whereNotNull('completed_at'))->orderBy('due_at')->orderBy('id')->limit(1001)->get();
        throw_if($activities->count()>1000,ValidationException::withMessages(['export'=>'มีมากกว่า 1,000 กิจกรรม กรุณากรองช่วงหรือผู้รับผิดชอบก่อนส่งออก']));
        $host=parse_url((string)config('app.url'),PHP_URL_HOST)?:'minterp.local';$calendarName='MintERP CRM · '.$this->label($filters['view'],$from,$to);$filename='crm-calendar-'.$from->format('Ymd').'-'.$to->format('Ymd').'.ics';
        return response()->streamDownload(function()use($activities,$host,$calendarName):void{$lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//MintERP//CRM Calendar//TH','CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-CALNAME:'.$this->icsEscape($calendarName)];foreach($activities as $activity){$lines=array_merge($lines,['BEGIN:VEVENT','UID:crm-activity-'.$activity->id.'@'.$host,'DTSTAMP:'.$activity->updated_at->copy()->utc()->format('Ymd\\THis\\Z'),'DTSTART:'.$activity->due_at->copy()->utc()->format('Ymd\\THis\\Z'),'DURATION:PT30M','SUMMARY:'.$this->icsEscape($activity->subject),'CATEGORIES:CRM-'.$activity->type,'STATUS:'.($activity->completed_at?'COMPLETED':'CONFIRMED'),'URL:'.$this->icsEscape(route('crm.opportunities.show',$activity->opportunity_id)),'END:VEVENT']);}$lines[]='END:VCALENDAR';echo implode("\r\n",array_map(fn(string $line)=>$this->icsLine($line),$lines))."\r\n";},$filename,['Content-Type'=>'text/calendar; charset=UTF-8']);
    }
    public function ownerOptions(Request $request):JsonResponse
    {
        $filters=$request->validate(['q'=>['nullable','string','max:100'],'page'=>['nullable','integer','min:1'],'team_id'=>['nullable','integer']]);$ids=$this->memberIds($request,$filters['team_id']??null,null);$search=trim((string)($filters['q']??''));$rows=User::query()->where('is_active',true)->whereHas('branches',fn(Builder $query)=>$query->where('branches.id',$this->branchId($request)))->when($ids!==null,fn(Builder $query)=>$query->whereIn('id',$ids))->when($search,fn(Builder $query)=>$query->where(fn(Builder $query)=>$query->where('name','like',"%{$search}%")->orWhere('employee_code','like',"%{$search}%")))->orderBy('name')->forPage((int)($filters['page']??1),31)->get(['id','name','employee_code']);return response()->json(['results'=>$rows->take(30)->map(fn(User $user)=>['id'=>$user->id,'text'=>($user->employee_code?$user->employee_code.' · ':'').$user->name])->values(),'pagination'=>['more'=>$rows->count()>30]]);
    }
    public function opportunityOptions(Request $request):JsonResponse
    {
        $filters=$request->validate(['q'=>['nullable','string','max:100'],'page'=>['nullable','integer','min:1']]);$ids=$this->memberIds($request,null,null);$search=trim((string)($filters['q']??''));$rows=Opportunity::query()->with('party:id,code,name')->where('branch_id',$this->branchId($request))->whereIn('stage',['NEW','CONTACTED','QUALIFIED','PROPOSAL','NEGOTIATION'])->when($ids!==null,fn(Builder $query)=>$query->whereIn('owner_id',$ids))->when($search,fn(Builder $query)=>$query->where(fn(Builder $query)=>$query->where('document_number','like',"%{$search}%")->orWhere('title','like',"%{$search}%")->orWhereHas('party',fn(Builder $party)=>$party->where('name','like',"%{$search}%")->orWhere('code','like',"%{$search}%"))))->orderByDesc('id')->forPage((int)($filters['page']??1),31)->get(['id','document_number','title','party_id']);return response()->json(['results'=>$rows->take(30)->map(fn(Opportunity $opportunity)=>['id'=>$opportunity->id,'text'=>$opportunity->document_number.' · '.$opportunity->title.' · '.($opportunity->party?->name??'-')])->values(),'pagination'=>['more'=>$rows->count()>30]]);
    }
    private function filters(Request $request):array{$data=$request->validate(['view'=>['nullable',Rule::in(['DAY','WEEK','MONTH'])],'date'=>['nullable','date_format:Y-m-d'],'team_id'=>['nullable','integer','exists:crm_sales_teams,id'],'user_id'=>['nullable','integer','exists:users,id'],'type'=>['nullable',Rule::in(['CALL','MEETING','TASK','NOTE'])],'status'=>['nullable',Rule::in(['OPEN','COMPLETED','ALL'])]]);return ['view'=>$data['view']??'MONTH','date'=>$data['date']??today()->toDateString(),'team_id'=>isset($data['team_id'])?(int)$data['team_id']:null,'user_id'=>isset($data['user_id'])?(int)$data['user_id']:null,'type'=>$data['type']??null,'status'=>$data['status']??'OPEN'];}
    private function range(string $view,string $date):array{$date=Carbon::parse($date);return match($view){'DAY'=>[$date->copy()->startOfDay(),$date->copy()->endOfDay()],'WEEK'=>[$date->copy()->startOfWeek()->startOfDay(),$date->copy()->endOfWeek()->endOfDay()],default=>[$date->copy()->startOfMonth()->startOfWeek()->startOfDay(),$date->copy()->endOfMonth()->endOfWeek()->endOfDay()]};}
    private function label(string $view,Carbon $from,Carbon $to):string{return $view==='DAY'?$from->translatedFormat('j F Y'):($view==='WEEK'?$from->translatedFormat('j M').' – '.$to->translatedFormat('j M Y'):$from->copy()->addDays(7)->translatedFormat('F Y'));}
    private function teams(Request $request):Builder{return SalesTeam::query()->where('branch_id',$this->branchId($request))->where('is_active',true)->when(!$request->user()->hasPermission('crm.team-work.view-all'),fn(Builder $query)=>$query->where('manager_id',$request->user()->id));}
    private function memberIds(Request $request,mixed $teamId,mixed $userId):?array{if($request->user()->hasPermission('crm.team-work.view-all')&&!$teamId&&!$userId)return null;if($teamId){$team=$this->teams($request)->findOrFail((int)$teamId);$ids=$team->members()->pluck('users.id')->map(fn($id)=>(int)$id)->all();}elseif($request->user()->hasPermission('crm.team-work.view-all'))$ids=null;else{$ids=$this->teams($request)->with('members:id')->get()->flatMap(fn(SalesTeam $team)=>$team->members->pluck('id'))->push($request->user()->id)->map(fn($id)=>(int)$id)->unique()->all();}if($userId){$userId=(int)$userId;abort_if($ids!==null&&!in_array($userId,$ids,true),403);return [$userId];}return $ids;}
    private function googleCalendarUrl(Activity $activity):string
    {
        $start=$activity->due_at->copy()->utc();$query=http_build_query(['action'=>'TEMPLATE','text'=>$activity->subject,'dates'=>$start->format('Ymd\\THis\\Z').'/'.$start->copy()->addMinutes(30)->format('Ymd\\THis\\Z'),'details'=>'เปิดใน MintERP: '.route('crm.opportunities.show',$activity->opportunity_id),'ctz'=>(string)config('app.timezone','Asia/Bangkok')],'','&',PHP_QUERY_RFC3986);
        return 'https://calendar.google.com/calendar/render?'.$query;
    }
    private function icsEscape(string $value):string{return str_replace(["\\","\r\n","\n","\r",';',','],["\\\\",'\\n','\\n','\\n','\\;','\\,'],$value);}
    private function icsLine(string $line):string{$lines=[];$prefix='';while(strlen($line)>($prefix===''?75:74)){$length=$prefix===''?75:74;$chunk=mb_strcut($line,0,$length,'UTF-8');$lines[]=$prefix.$chunk;$line=substr($line,strlen($chunk));$prefix=' ';}$lines[]=$prefix.$line;return implode("\r\n",$lines);}
    private function branchId(Request $request):int{return (int)$request->attributes->get('selectedBranch')->id;}
}
